var i=`0507-sabich`;var n=`world-0507`;var a=`IL`;var r=`western-asia`;var s=4;var o=53;var g={en:`Sabich`,ua:`Сабіх`};var l={en:`A traditional dish from Israel, centered on eggplant, chicken egg, pita bread, tahini. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Ізраїль. Основні складники: баклажан, куряче яйце, піта, тахіні. Домашній варіант із кількостями продуктів за етапами приготування.`};var u=[{en:`Cut the vegetables evenly and roast at 200°C for about 30 minutes until tender and lightly charred.`,ua:`Наріжте овочі рівномірно та запікайте при 200°C приблизно 30 хвилин до м’якості й легкої підпеченої скоринки.`,t:[`roasting`],m:30,i:[[`eggplant`,530,`g`]]},{en:`Boil the eggs for about 9 minutes, cool promptly in cold water, peel and prepare as required.`,ua:`Варіть яйця приблизно 9 хвилин, швидко охолодіть у холодній воді, очистьте та підготуйте за потреби.`,t:[`hard-boiling-eggs`],m:9,i:[[`chicken-egg`,4,`pcs`]]},{en:`Toast these ingredients over medium heat for about 5 minutes, turning frequently to prevent scorching.`,ua:`Підсмажуйте зазначені складники на середньому вогні приблизно 5 хвилин, часто перевертаючи, щоб не підгоріли.`,t:[`dry-toasting`],m:5,i:[[`pita-bread`,4,`pcs`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:9,i:[[`tahini`,75,`g`],[`lemon-juice`,35,`ml`],[`tomato`,220,`g`],[`cucumber`,170,`g`],[`fermented-cucumber`,120,`g`]]}];var d={slug:i,id:n,country:`IL`,region:r,servings:4,minutes:53,title:g,text:l,steps:u};export{a as country,d as default,n as id,o as minutes,r as region,s as servings,i as slug,u as steps,l as text,g as title};